# ============================================================
# GBP/USD LONG - TRANSACTION COST STRESS TEST
#
# READ-ONLY RESEARCH. NEVER SUBMITS ORDERS.
#
# PURPOSE
# ------------------------------------------------------------
# Compare CURRENT GBP/USD long against ALT_06 after explicitly
# varying the assumed adverse entry cost on EVERY GBP/USD trade.
#
# This does NOT subtract a flat R penalty.
#
# For each GBP/USD trade and cost level:
#
#   stressed_entry =
#       reference_entry + cost_pips * 0.0001
#
#   actual_risk =
#       stressed_entry - stop
#
#   winner R =
#       (target - stressed_entry) / actual_risk
#
#   loser R =
#       (stop - stressed_entry) / actual_risk
#
# Target remains based on the original REFERENCE signal-close
# risk, matching the locked historical convention.
#
# Other portfolio strategies remain unchanged. Only GBP/USD
# transaction cost is varied.
#
# Baseline portfolio already contains:
#   USD/CAD Candidate B
#   EUR/GBP Candidate B
#   EUR/USD Candidate A
#   CURRENT GBP/USD long
#
# Main stress scenarios:
#   0.50, 0.75, 1.00, 1.25, 1.50, 2.00, 2.50 pips
#
# A fine 0.05-pip grid from 0.50 to 3.00 is also run to locate
# the approximate portfolio crossover between CURRENT and ALT_06.
#
# Portfolio compounding:
#   £100 start
#   1% realised balance risk at ENTRY
#   overlapping trades retain entry risk amount
#   EXIT before ENTRY at equal timestamps
# ============================================================


PIP_SIZE = 0.0001
