def read_portfolio(text):
    df = pd.read_csv(
        io.StringIO(text)
    )

    for col in [
        "entry_time_utc",
        "exit_time_utc",
    ]:
        df[col] = pd.to_datetime(
            df[col],
            utc=True,
        )

    df["result_r"] = pd.to_numeric(
        df["result_r"],
        errors="coerce",
    )

    return df


def read_source(text):
    df = pd.read_csv(
        io.StringIO(text)
    )

    df["signal_time"] = pd.to_datetime(
        df["signal_time"],
        utc=True,
    )

    df["exit_time"] = pd.to_datetime(
        df["exit_time"],
        utc=True,
    )

    for col in [
        "reference_entry",
        "stop",
        "target",
    ]:
        df[col] = pd.to_numeric(
            df[col],
            errors="coerce",
        )

    return df


def stressed_trade_log(
    source,
    strategy_name,
    cost_pips,
):
    rows = []

    adverse_price = (
        float(cost_pips)
        * PIP_SIZE
    )

    for _, trade in source.iterrows():
        reference_entry = float(
            trade["reference_entry"]
        )

        stop = float(
            trade["stop"]
        )

        target = float(
            trade["target"]
        )

        stressed_entry = (
            reference_entry
            + adverse_price
        )

        actual_risk = (
            stressed_entry
            - stop
        )

        if actual_risk <= 0:
            continue

        reason = str(
            trade["exit_reason"]
        )

        if reason.startswith(
            "TARGET"
        ):
            exit_price = target
        else:
            exit_price = stop

        result_r = (
            exit_price
            - stressed_entry
        ) / actual_risk

        rows.append({
            "instrument":
                "GBP_USD",
            "side":
                "BUY",
            "strategy":
                strategy_name,
            "entry_time_utc":
                trade["signal_time"],
            "exit_time_utc":
                trade["exit_time"],
            "reference_entry":
                reference_entry,
            "backtest_entry":
                stressed_entry,
            "stop":
                stop,
            "target":
                target,
            "exit_reason":
                reason,
            "result_r":
                result_r,
            "reward_risk":
                REWARD_RISK,
        })

    return pd.DataFrame(rows)


def restrict_window(
    df,
    start,
    end,
):
    return df[
        (
            df["entry_time_utc"]
            >= start
        )
        &
        (
            df["entry_time_utc"]
            <= end
        )
    ].copy()


def replace_gbpusd_buy(
    baseline,
    replacement,
):
    start = baseline[
        "entry_time_utc"
    ].min()

    end = baseline[
        "entry_time_utc"
    ].max()

    kept = baseline[
        ~(
            (
                baseline["instrument"]
                == "GBP_USD"
            )
            &
            (
                baseline["side"]
                == "BUY"
            )
        )
    ].copy()

    replacement = restrict_window(
        replacement,
        start,
        end,
    )

    return (
        pd.concat(
            [
                kept,
                replacement,
            ],
            ignore_index=True,
        )
        .sort_values(
            [
                "entry_time_utc",
                "exit_time_utc",
                "instrument",
                "side",
            ]
        )
        .reset_index(drop=True)
    )


def simple_stats(df):
    r = df[
        "result_r"
    ].astype(float)

    winners = r[
        r > 0
    ]

    losers = r[
        r < 0
    ]

    gross_profit = (
        winners.sum()
    )

    gross_loss = abs(
        losers.sum()
    )

    if gross_loss > 0:
        pf = (
            gross_profit
            / gross_loss
        )
    elif gross_profit > 0:
        pf = 999.0
    else:
        pf = 0.0

    total_r = r.sum()

    return {
        "trades":
            len(df),
        "winners":
            len(winners),
        "losers":
            len(losers),
        "win_rate":
            (
                len(winners)
                / len(df)
                * 100.0
                if len(df)
                else 0.0
            ),
        "profit_factor":
            pf,
        "total_r":
            total_r,
        "expectancy_r":
            (
                total_r
                / len(df)
                if len(df)
                else 0.0
            ),
    }


def compound(
    df,
    starting_balance=100.0,
    risk_percent=0.01,
):
    records = (
        df.reset_index(drop=True)
        .to_dict("records")
    )

    events = []

    for i, trade in enumerate(records):
        events.append((
            pd.Timestamp(
                trade[
                    "entry_time_utc"
                ]
            ).to_pydatetime(),
            1,
            "ENTRY",
            i,
        ))

        events.append((
            pd.Timestamp(
                trade[
                    "exit_time_utc"
                ]
            ).to_pydatetime(),
            0,
            "EXIT",
            i,
        ))

    # EXIT before ENTRY at identical timestamps.
    events.sort(
        key=lambda x: (
            x[0],
            x[1],
        )
    )

    balance = float(
        starting_balance
    )

    risk_at_entry = {}

    peak = balance
    max_dd_pct = 0.0

    for (
        event_time,
        priority,
        event_type,
        i,
    ) in events:
        trade = records[i]

        if event_type == "ENTRY":
            risk_at_entry[i] = (
                balance
                * risk_percent
            )

        else:
            risk_amount = (
                risk_at_entry.get(i)
            )

            if risk_amount is None:
                continue

            balance += (
                risk_amount
                * float(
                    trade[
                        "result_r"
                    ]
                )
            )

            peak = max(
                peak,
                balance,
            )

            if peak > 0:
                dd = (
                    (
                        balance
                        - peak
                    )
                    / peak
                    * 100.0
                )

                max_dd_pct = min(
                    max_dd_pct,
                    dd,
                )

    return {
        "ending_balance":
            balance,
        "return_pct":
            (
                balance
                / starting_balance
                - 1.0
            ) * 100.0,
        "max_closed_equity_dd_pct":
            max_dd_pct,
    }


def evaluate(
    baseline,
    replacement,
):
    portfolio = (
        replace_gbpusd_buy(
            baseline,
            replacement,
        )
    )

    s = simple_stats(
        portfolio
    )

    c = compound(
        portfolio
    )

    return {
        "trades":
            s["trades"],
        "win_rate":
            s["win_rate"],
        "profit_factor":
            s["profit_factor"],
        "total_r":
            s["total_r"],
        "expectancy_r":
            s["expectancy_r"],
        "ending_balance":
            c["ending_balance"],
        "return_pct":
            c["return_pct"],
        "max_dd_pct":
            c[
                "max_closed_equity_dd_pct"
            ],
    }


def evaluate_cost(
    window_name,
    baseline,
    current_source,
    alt_source,
    cost_pips,
):
    current_log = (
        stressed_trade_log(
            current_source,
            "CURRENT_LIVE",
            cost_pips,
        )
    )

    alt_log = (
        stressed_trade_log(
            alt_source,
            "ALT_06",
            cost_pips,
        )
    )

    current = evaluate(
        baseline,
        current_log,
    )

    alt = evaluate(
        baseline,
        alt_log,
    )

    return {
        "window":
            window_name,
        "cost_pips":
            float(cost_pips),

        "current_gbpusd_trades_full":
            len(current_log),
        "alt06_gbpusd_trades_full":
            len(alt_log),

        "current_portfolio_trades":
            current["trades"],
        "current_pf":
            current[
                "profit_factor"
            ],
        "current_total_r":
            current["total_r"],
        "current_expectancy_r":
            current[
                "expectancy_r"
            ],
        "current_ending_balance":
            current[
                "ending_balance"
            ],
        "current_return_pct":
            current[
                "return_pct"
            ],
        "current_dd_pct":
            current[
                "max_dd_pct"
            ],

        "alt06_portfolio_trades":
            alt["trades"],
        "alt06_pf":
            alt[
                "profit_factor"
            ],
        "alt06_total_r":
            alt["total_r"],
        "alt06_expectancy_r":
            alt[
                "expectancy_r"
            ],
        "alt06_ending_balance":
            alt[
                "ending_balance"
            ],
        "alt06_return_pct":
            alt[
                "return_pct"
            ],
        "alt06_dd_pct":
            alt[
                "max_dd_pct"
            ],

        "alt_minus_current_pf":
            alt[
                "profit_factor"
            ]
            - current[
                "profit_factor"
            ],

        "alt_minus_current_total_r":
            alt[
                "total_r"
            ]
            - current[
                "total_r"
            ],

        "alt_minus_current_expectancy_r":
            alt[
                "expectancy_r"
            ]
            - current[
                "expectancy_r"
            ],

        "alt_minus_current_ending_balance":
            alt[
                "ending_balance"
            ]
            - current[
                "ending_balance"
            ],

        "alt_minus_current_dd_pct":
            alt[
                "max_dd_pct"
            ]
            - current[
                "max_dd_pct"
            ],
    }


def rounded_dataframe(rows):
    df = pd.DataFrame(rows)

    numeric_cols = (
        df.select_dtypes(
            include="number"
        ).columns
    )

    df[
        numeric_cols
    ] = (
        df[
            numeric_cols
        ].round(9)
    )

    return df


def crossover_rows(
    fine_df,
):
    rows = []

    for window in [
        "5Y",
        "2Y",
    ]:
        part = (
            fine_df[
                fine_df["window"]
                == window
            ]
            .sort_values(
                "cost_pips"
            )
            .reset_index(
                drop=True
            )
        )

        for metric in [
            "alt_minus_current_total_r",
            "alt_minus_current_ending_balance",
            "alt_minus_current_pf",
        ]:
            crossing = None

            for i in range(
                1,
                len(part),
            ):
                prev = float(
                    part.loc[
                        i - 1,
                        metric,
                    ]
                )

                curr = float(
                    part.loc[
                        i,
                        metric,
                    ]
                )

                if (
                    prev == 0
                    or curr == 0
                    or (
                        prev < 0
                        and curr > 0
                    )
                    or (
                        prev > 0
                        and curr < 0
                    )
                ):
                    crossing = {
                        "window":
                            window,
                        "metric":
                            metric,
                        "lower_cost_pips":
                            float(
                                part.loc[
                                    i - 1,
                                    "cost_pips",
                                ]
                            ),
                        "lower_delta":
                            prev,
                        "upper_cost_pips":
                            float(
                                part.loc[
                                    i,
                                    "cost_pips",
                                ]
                            ),
                        "upper_delta":
                            curr,
                    }
                    break

            if crossing is None:
                first = float(
                    part.iloc[0][
                        metric
                    ]
                )

                last = float(
                    part.iloc[-1][
                        metric
                    ]
                )

                crossing = {
                    "window":
                        window,
                    "metric":
                        metric,
                    "lower_cost_pips":
                        None,
                    "lower_delta":
                        first,
                    "upper_cost_pips":
                        None,
                    "upper_delta":
                        last,
                    "note":
                        (
                            "No crossover inside "
                            "0.50-3.00 pip grid"
                        ),
                }

            rows.append(
                crossing
            )

    return pd.DataFrame(rows)


def run_analysis():
    try:
        STATUS.update({
            "state":
                "loading",
            "message":
                "Loading embedded portfolio and GBP/USD trade logs",
        })

        base5 = read_portfolio(
            BASE5
        )

        base2 = read_portfolio(
            BASE2
        )

        current_source = (
            read_source(
                CURRENT_SOURCE
            )
        )

        alt_source = (
            read_source(
                ALT_SOURCE
            )
        )

        main_rows = []
        fine_rows = []

        STATUS.update({
            "state":
                "running_main",
            "message":
                "Running main cost scenarios",
        })

        for cost in MAIN_COSTS_PIPS:
            for (
                window,
                baseline,
            ) in [
                ("5Y", base5),
                ("2Y", base2),
            ]:
                main_rows.append(
                    evaluate_cost(
                        window,
                        baseline,
                        current_source,
                        alt_source,
                        cost,
                    )
                )

        main_df = (
            rounded_dataframe(
                main_rows
            )
        )

        STATUS.update({
            "state":
                "running_fine",
            "message":
                "Running fine crossover grid",
        })

        for cost in FINE_COSTS_PIPS:
            for (
                window,
                baseline,
            ) in [
                ("5Y", base5),
                ("2Y", base2),
            ]:
                fine_rows.append(
                    evaluate_cost(
                        window,
                        baseline,
                        current_source,
                        alt_source,
                        cost,
                    )
                )

        fine_df = (
            rounded_dataframe(
                fine_rows
            )
        )

        crossover = crossover_rows(
            fine_df
        )

        main_df.to_csv(
            os.path.abspath(
                OUTPUT_MAIN
            ),
            index=False,
        )

        fine_df.to_csv(
            os.path.abspath(
                OUTPUT_FINE
            ),
            index=False,
        )

        crossover.to_csv(
            os.path.abspath(
                OUTPUT_CROSSOVER
            ),
            index=False,
        )

        STATUS.update({
            "state":
                "complete",
            "message":
                "GBP/USD transaction cost stress test complete",
            "outputs": {
                "main":
                    OUTPUT_MAIN,
                "fine":
                    OUTPUT_FINE,
                "crossover":
                    OUTPUT_CROSSOVER,
            },
        })

        print()
        print(
            "=" * 100
        )
        print(
            "GBP/USD TRANSACTION COST STRESS TEST COMPLETE"
        )
        print(
            "=" * 100
        )
        print(
            main_df.to_string(
                index=False
            ),
            flush=True,
        )
        print()
        print(
            "CROSSOVER CHECK"
        )
        print(
            crossover.to_string(
                index=False
            ),
            flush=True,
        )

    except Exception as error:
        STATUS.update({
            "state":
                "error",
            "message":
                str(error),
        })

        print(
            "ERROR:",
            error,
            flush=True,
        )


