@app.route("/status")
def status():
    return jsonify(
        STATUS
    )


def send_output(filename):
    path = os.path.abspath(
        filename
    )

    if not os.path.exists(
        path
    ):
        return jsonify({
            "status":
                "not_ready",
            "message":
                f"{filename} is not ready yet",
        }), 404

    return send_file(
        path,
        as_attachment=True,
        download_name=filename,
    )


@app.route(
    "/download/main"
)
def download_main():
    return send_output(
        OUTPUT_MAIN
    )


@app.route(
    "/download/fine"
)
def download_fine():
    return send_output(
        OUTPUT_FINE
    )


@app.route(
    "/download/crossover"
)
def download_crossover():
    return send_output(
        OUTPUT_CROSSOVER
    )


