    thread = threading.Thread(
        target=run_analysis,
        name=(
            "gbpusd-transaction-cost-stress"
        ),
        daemon=True,
    )

    thread.start()

    port = int(
        os.getenv(
            "PORT",
            5000,
        )
    )

    app.run(
        host="0.0.0.0",
        port=port,
        debug=False,
    )
